2) FIX: In /luxon/src/interval.js, the static method `fromISO(text, opts)` currently calls DateTime.fromISO directly. When Settings.throwOnInvalid is true, DateTime.fromISO throws InvalidDateTimeError for an unparsable half (e.g. the duration half of '2007-03-01T13:00:00/P1Y2M10DT2H30M'), so the duration branch is never reached and valid ISO intervals wrongly throw. Fix it by wrapping each DateTime.fromISO call in try/catch and treating a thrown error as 'not valid', keeping the rest of the logic identical. The intended resulting code is:

  static fromISO(text, opts) {
    const [s, e] = (text || "").split("/", 2);
    if (s && e) {
      let start, startIsValid;
      try {
        start = DateTime.fromISO(s, opts);
        startIsValid = start.isValid;
      } catch (e) {
        startIsValid = false;
      }

      let end, endIsValid;
      try {
        end = DateTime.fromISO(e, opts);
        endIsValid = end.isValid;
      } catch (e) {
        endIsValid = false;
      }

      if (startIsValid && endIsValid) {
        return Interval.fromDateTimes(start, end);
      }

      if (startIsValid) {
        const dur = Duration.fromISO(e, opts);
        if (dur.isValid) {
          return Interval.after(start, dur);
        }
      } else if (endIsValid) {
        const dur = Duration.fromISO(s, opts);
        if (dur.isValid) {
          return Interval.before(end, dur);
        }
      }
    }
    return Interval.invalid("unparsable", `the input "${text}" can't be parsed asISO 8601`);
  }

